tool.command:
mkdir -p libreqda_data ;
export HOME=\$PWD/libreqda_data ;
python3 -c 'import os,secrets;db="sqlite:///"+os.path.join(os.getcwd(),"libreqda_data","libreqda.sqlite3");lines=["NAME = \x27LibreQDA\x27","PORT = 7465","BIND_ADDRESS = \x270.0.0.0\x27","SECRET_KEY = \x27%s\x27" % secrets.token_hex(32),"DATABASE = \x27%s\x27" % db,"TOS_FILE = None","X_HEADERS = False","EMAIL = \x27LibreQDA <noreply@localhost>\x27","MAIL_SERVER = dict(ssl=False, host=\x27localhost\x27, port=25)","COOKIES_PROMPT = False","MULTIUSER = False","UNIX_SOCKET = True","if UNIX_SOCKET:","    import tornado.web","    def _gxy_cookie(orig):","        def fix(self, name, value, *args, **kwargs):","            kwargs.setdefault(\x27samesite\x27, \x27None\x27)","            kwargs.setdefault(\x27secure\x27, True)","            return orig(self, name, value, *args, **kwargs)","        return fix","    tornado.web.RequestHandler.set_cookie = _gxy_cookie(tornado.web.RequestHandler.set_cookie)","    del _gxy_cookie, tornado","    import taguette.web.base as _gxy_base","    _gxy_base.BaseHandler.get_current_user = lambda self: \x27admin\x27","    def _gxy_frames(orig):","        def dh(self):","            orig(self)","            self.clear_header(\x27X-Frame-Options\x27)","            self.set_header(\x27Content-Security-Policy\x27, \x27frame-ancestors *\x27)","        return dh","    _gxy_base.BaseHandler.set_default_headers = _gxy_frames(_gxy_base.BaseHandler.set_default_headers)","    del _gxy_frames, _gxy_base"];open("libreqda_server_config.py","w").write("\n".join(lines))' ;
exec libreqda --no-browser server libreqda_server_config.py

